(459, 'fs_api_cache', 'a:6:{s:60:\"get:/v1/installs/20815745/addons.json?enriched=true&count=50\";O:8:\"stdClass\":3:{s:6:\"result\";O:8:\"stdClass\":1:{s:7:\"plugins\";a:4:{i:0;O:8:\"stdClass\":37:{s:16:\"parent_plugin_id\";s:3:\"843\";s:12:\"developer_id\";s:3:\"308\";s:8:\"store_id\";s:3:\"166\";s:10:\"install_id\";s:8:\"13470153\";s:4:\"slug\";s:23:\"foogallery-user-uploads\";s:5:\"title\";s:23:\"FooGallery User Uploads\";s:11:\"environment\";i:0;s:4:\"icon\";s:100:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/14147/icons/54e01bb41212f0df698b9066945f8cfe.png\";s:15:\"default_plan_id\";s:5:\"23683\";s:5:\"plans\";i:23683;s:8:\"features\";s:29:\"16161,16162,16164,16163,16165\";s:17:\"money_back_period\";i:30;s:13:\"refund_policy\";s:8:\"flexible\";s:20:\"is_consumptive_usage\";b:0;s:24:\"annual_renewals_discount\";N;s:22:\"renewals_discount_type\";s:10:\"percentage\";s:31:\"lifetime_license_proration_days\";i:30;s:11:\"is_released\";b:1;s:15:\"is_sdk_required\";b:1;s:18:\"is_pricing_visible\";b:1;s:19:\"is_wp_org_compliant\";b:0;s:6:\"is_off\";b:0;s:24:\"is_only_for_new_installs\";b:0;s:14:\"installs_limit\";N;s:19:\"free_releases_count\";i:0;s:22:\"premium_releases_count\";i:22;s:17:\"accepted_payments\";i:0;s:7:\"plan_id\";s:1:\"0\";s:4:\"type\";s:6:\"plugin\";s:10:\"type_alias\";N;s:9:\"is_static\";b:0;s:10:\"public_key\";s:32:\"pk_f311a65bfd8e62a67fb0270d64733\";s:2:\"id\";s:5:\"14147\";s:7:\"created\";s:19:\"2023-10-31 18:32:31\";s:7:\"updated\";s:19:\"2026-10-20 14:36:33\";s:4:\"info\";O:8:\"stdClass\":13:{s:9:\"plugin_id\";s:5:\"14147\";s:3:\"url\";N;s:11:\"description\";s:630:\"User Uploads is a FooGallery addon, and works with FooGallery Free, and FooGallery PRO Starter, Expert and Commerce. With this, you can allow users to upload their own images to your gallery, saving you time as you no longer need to curate all the images yourself. User Uploads turns your gallery into a dynamic, creative and interactive space, that can help engage your audience. \n\nYou still have control - you set the max number of images that can be uploaded and the max file size. You set whether logged-in users or anyone can upload images. And all images appear in moderation first, so you have final say in what gets added.\";s:17:\"short_description\";s:135:\"FooGallery User Uploads lets your users upload their own images to your gallery, creating a dynamic, engaging space for your community.\";s:10:\"banner_url\";s:69:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/14147/banner.jpeg\";s:15:\"card_banner_url\";s:74:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/14147/card_banner.jpeg\";s:15:\"selling_point_0\";s:60:\"Inspire creativity with a dynamic community-focused gallery.\";s:15:\"selling_point_1\";s:53:\"Save time and effort - users submit their own images.\";s:15:\"selling_point_2\";s:43:\"Increase user engagement and interactivity.\";s:11:\"screenshots\";O:8:\"stdClass\":2:{s:12:\"screenshot_0\";s:75:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/14147/screenshots/0.png\";s:12:\"screenshot_1\";s:75:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/14147/screenshots/1.png\";}s:2:\"id\";s:4:\"3844\";s:7:\"created\";s:19:\"2023-10-31 18:58:42\";s:7:\"updated\";s:19:\"2024-01-12 10:29:19\";}s:12:\"premium_slug\";s:23:\"foogallery-user-uploads\";}i:1;O:8:\"stdClass\":37:{s:16:\"parent_plugin_id\";s:3:\"843\";s:12:\"developer_id\";s:3:\"308\";s:8:\"store_id\";s:3:\"166\";s:10:\"install_id\";s:8:\"18639709\";s:4:\"slug\";s:17:\"foogallery-social\";s:5:\"title\";s:17:\"FooGallery Social\";s:11:\"environment\";i:0;s:4:\"icon\";s:100:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/20776/icons/fb7e14441d8dffada050616bd5f19fee.png\";s:15:\"default_plan_id\";s:5:\"34665\";s:5:\"plans\";i:34665;s:8:\"features\";N;s:17:\"money_back_period\";i:30;s:13:\"refund_policy\";s:8:\"flexible\";s:20:\"is_consumptive_usage\";b:0;s:24:\"annual_renewals_discount\";N;s:22:\"renewals_discount_type\";s:10:\"percentage\";s:31:\"lifetime_license_proration_days\";i:30;s:11:\"is_released\";b:1;s:15:\"is_sdk_required\";b:1;s:18:\"is_pricing_visible\";b:1;s:19:\"is_wp_org_compliant\";b:0;s:6:\"is_off\";b:0;s:24:\"is_only_for_new_installs\";b:0;s:14:\"installs_limit\";N;s:19:\"free_releases_count\";i:0;s:22:\"premium_releases_count\";i:16;s:17:\"accepted_payments\";i:0;s:7:\"plan_id\";s:1:\"0\";s:4:\"type\";s:6:\"plugin\";s:10:\"type_alias\";N;s:9:\"is_static\";b:0;s:10:\"public_key\";s:32:\"pk_73dfd509754654f571485b3a03642\";s:2:\"id\";s:5:\"20776\";s:7:\"created\";s:19:\"2025-09-17 08:51:48\";s:7:\"updated\";s:19:\"2026-10-15 04:25:45\";s:4:\"info\";O:8:\"stdClass\":13:{s:9:\"plugin_id\";s:5:\"20776\";s:3:\"url\";s:77:\"https://fooplugins.com/foogallery-wordpress-gallery-plugin/foogallery-social/\";s:11:\"description\";s:1008:\"FooGallery Social makes gallery engagement simple. Your galleries don’t just showcase visuals anymore — they spark interaction. Empower visitors to like, comment, and share your images or videos directly from the gallery. Likes: Add a simple heart icon to each gallery image so visitors can quickly express appreciation. Control who can like (public or logged-in users), display total likes, and protect against spam with built-in abuse prevention. Comments: Add a full commenting system directly into your gallery lightbox. Built on top of WordPress’s native comments, so all your moderation, login, and consent settings still apply. Customize layout, position, and thread behavior for a seamless experience. Social Sharing: Let your visitors spread your visuals effortlessly. Add customizable share icons for all major social platforms right inside the lightbox. Choose which networks to display, adjust icon size and placement, and decide what link gets shared — from product pages to custom URLs.\";s:17:\"short_description\";s:112:\"Turn every image into a social experience — with likes, comments, and easy sharing built right into FooGallery\";s:10:\"banner_url\";s:69:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/20776/banner.jpeg\";s:15:\"card_banner_url\";s:74:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/20776/card_banner.jpeg\";s:15:\"selling_point_0\";s:30:\"Like gallery images and videos\";s:15:\"selling_point_1\";s:40:\"Comment on gallery items in the lightbox\";s:15:\"selling_point_2\";s:60:\"Share images to social platforms or enable download or email\";s:11:\"screenshots\";N;s:2:\"id\";s:4:\"5558\";s:7:\"created\";s:19:\"2025-09-17 08:52:22\";s:7:\"updated\";s:19:\"2025-11-11 11:24:24\";}s:12:\"premium_slug\";s:17:\"foogallery-social\";}i:2;O:8:\"stdClass\":37:{s:16:\"parent_plugin_id\";s:3:\"843\";s:12:\"developer_id\";s:3:\"308\";s:8:\"store_id\";s:3:\"166\";s:10:\"install_id\";s:8:\"18712135\";s:4:\"slug\";s:21:\"foogallery-whitelabel\";s:5:\"title\";s:21:\"FooGallery Whitelabel\";s:11:\"environment\";i:0;s:4:\"icon\";s:100:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/20952/icons/4c5fc6e7fe64d183efa8af0080c09274.png\";s:15:\"default_plan_id\";s:5:\"34936\";s:5:\"plans\";i:34936;s:8:\"features\";N;s:17:\"money_back_period\";i:30;s:13:\"refund_policy\";s:8:\"flexible\";s:20:\"is_consumptive_usage\";b:0;s:24:\"annual_renewals_discount\";N;s:22:\"renewals_discount_type\";s:10:\"percentage\";s:31:\"lifetime_license_proration_days\";i:30;s:11:\"is_released\";b:1;s:15:\"is_sdk_required\";b:1;s:18:\"is_pricing_visible\";b:1;s:19:\"is_wp_org_compliant\";b:1;s:6:\"is_off\";b:0;s:24:\"is_only_for_new_installs\";b:0;s:14:\"installs_limit\";N;s:19:\"free_releases_count\";i:0;s:22:\"premium_releases_count\";i:5;s:17:\"accepted_payments\";i:0;s:7:\"plan_id\";s:1:\"0\";s:4:\"type\";s:6:\"plugin\";s:10:\"type_alias\";N;s:9:\"is_static\";b:0;s:10:\"public_key\";s:32:\"pk_7783bbab66393eeb4bf90f340c908\";s:2:\"id\";s:5:\"20952\";s:7:\"created\";s:19:\"2025-09-29 09:11:29\";s:7:\"updated\";s:19:\"2026-10-21 17:55:34\";s:4:\"info\";O:8:\"stdClass\":13:{s:9:\"plugin_id\";s:5:\"20952\";s:3:\"url\";N;s:11:\"description\";s:572:\"The White Label Addon for FooGallery empowers agencies and freelancers to deliver a fully branded gallery experience to clients. Rebrand FooGallery with your own plugin name and shortcode, hide or rename menu items, and control which user roles can access specific settings or features. Simplify the WordPress dashboard by disabling unnecessary options, reducing client confusion and support requests. With this addon, you maintain full control, strengthen your brand presence, and offer clients a clean, professional interface that feels custom-built — not third-party.\";s:17:\"short_description\";s:68:\"Rebrand your gallery solution and deliver it as your own to clients.\";s:10:\"banner_url\";s:69:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/20952/banner.jpeg\";s:15:\"card_banner_url\";s:74:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/20952/card_banner.jpeg\";s:15:\"selling_point_0\";s:67:\"Rebrand the gallery plugin as your own (no “FooGallery” label).\";s:15:\"selling_point_1\";s:82:\"Control visibility of settings and features by user-role (e.g. admins vs editors).\";s:15:\"selling_point_2\";s:68:\"Maintain full control while your clients enjoy a branded experience.\";s:11:\"screenshots\";O:8:\"stdClass\":1:{s:12:\"screenshot_0\";s:75:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/20952/screenshots/0.png\";}s:2:\"id\";s:4:\"5691\";s:7:\"created\";s:19:\"2025-10-21 10:26:53\";s:7:\"updated\";N;}s:12:\"premium_slug\";s:29:\"foogallery-whitelabel-premium\";}i:3;O:8:\"stdClass\":37:{s:16:\"parent_plugin_id\";s:3:\"843\";s:12:\"developer_id\";s:3:\"308\";s:8:\"store_id\";s:3:\"166\";s:10:\"install_id\";s:8:\"19990410\";s:4:\"slug\";s:19:\"foogallery-proofing\";s:5:\"title\";s:19:\"FooGallery Proofing\";s:11:\"environment\";i:0;s:4:\"icon\";s:100:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/29026/icons/349fe1e69059e23e727c3de6101e29a0.png\";s:15:\"default_plan_id\";s:5:\"47721\";s:5:\"plans\";i:47721;s:8:\"features\";N;s:17:\"money_back_period\";i:30;s:13:\"refund_policy\";s:8:\"flexible\";s:20:\"is_consumptive_usage\";b:0;s:24:\"annual_renewals_discount\";N;s:22:\"renewals_discount_type\";s:10:\"percentage\";s:31:\"lifetime_license_proration_days\";i:30;s:11:\"is_released\";b:1;s:15:\"is_sdk_required\";b:1;s:18:\"is_pricing_visible\";b:1;s:19:\"is_wp_org_compliant\";b:0;s:6:\"is_off\";b:0;s:24:\"is_only_for_new_installs\";b:0;s:14:\"installs_limit\";N;s:19:\"free_releases_count\";i:0;s:22:\"premium_releases_count\";i:11;s:17:\"accepted_payments\";i:0;s:7:\"plan_id\";s:1:\"0\";s:4:\"type\";s:6:\"plugin\";s:10:\"type_alias\";N;s:9:\"is_static\";b:0;s:10:\"public_key\";s:32:\"pk_7944b79a1f3ed5750c2933e66c4c7\";s:2:\"id\";s:5:\"29026\";s:7:\"created\";s:19:\"2026-05-03 11:03:05\";s:7:\"updated\";s:19:\"2026-10-12 11:02:27\";s:4:\"info\";O:8:\"stdClass\":13:{s:9:\"plugin_id\";s:5:\"29026\";s:3:\"url\";s:75:\"https://fooplugins.com/foogallery-wordpress-gallery-plugin/client-proofing/\";s:11:\"description\";s:2826:\"<h2>Simple, reliable client proofing for FooGallery</h2>\n\n<p>FooGallery Proofing turns the galleries you already use into private client approval experiences. Create a proofing session, share the private link and let your client select, reject and comment on images from a familiar, distraction-free gallery.</p>\n\n<p>There is no separate collection to build, no client account to create and no checkout standing between your client and a completed proof.</p>\n\n<h3>Turn an existing gallery into a private proof</h3>\n\n<p>Start with any FooGallery gallery and create a dedicated proofing session for your client. Add their details, choose an expiry date and send a personalized invitation—or copy the private link and share it yourself.</p>\n\n<ul>\n<li>Create proofs from galleries you have already built</li>\n<li>Share private, tokenized client links</li>\n<li>Set optional minimum and maximum selection limits</li>\n<li>Control whether clients can reject images or leave comments</li>\n<li>Preview the client experience before sharing</li>\n</ul>\n\n<h3>Give clients an effortless approval experience</h3>\n\n<p>Clients can review images, mark their favorites, reject unwanted shots and leave image-specific notes without logging in. Their progress is autosaved as they work, helping protect selections from accidental refreshes or temporary connection problems.</p>\n\n<p>When the proof is ready, the client submits their choices in one clear action. The submitted proof becomes read-only, giving you a dependable record of their final decisions.</p>\n\n<ul>\n<li>No client account or WordPress login required</li>\n<li>Select, reject and comment directly from the gallery</li>\n<li>Automatic saving throughout the review</li>\n<li>Clear selection counts and limit guidance</li>\n<li>Customizable text for the public proofing experience</li>\n</ul>\n\n<h3>Turn client feedback into a clear production handoff</h3>\n\n<p>Stop searching through email threads for filenames and feedback. FooGallery Proofing organizes selected and rejected images into visual review grids, with client comments displayed alongside the relevant files.</p>\n\n<p>Receive an email notification when a proof is submitted, review the complete session history and download the results as CSV or JSON for editing, retouching, fulfillment or record keeping.</p>\n\n<ul>\n<li>Visual grids for selected and rejected images</li>\n<li>Image filenames and client comments kept together</li>\n<li>Customizable invitation and submission emails</li>\n<li>Email and activity logs for each proof</li>\n<li>CSV and JSON exports with image IDs, filenames, statuses and comments</li>\n</ul>\n\n<p><b>FooGallery Proofing gives photographers a faster path from gallery delivery to confident client approval—with less administration, fewer email exchanges and no need to rebuild their workflow.</b></p>\";s:17:\"short_description\";s:128:\"Turn any FooGallery gallery into a private, autosaving client proof—without rebuilding galleries or requiring client accounts.\";s:10:\"banner_url\";s:68:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/29026/banner.png\";s:15:\"card_banner_url\";s:73:\"https://s3-us-west-2.amazonaws.com/freemius/plugins/29026/card_banner.png\";s:15:\"selling_point_0\";s:109:\"Create a client proofing session from any FooGallery gallery—no rebuilding or separate collection workflow.\";s:15:\"selling_point_1\";s:106:\"Clients can select, reject, comment and submit without an account, while autosave protects every decision.\";s:15:\"selling_point_2\";s:92:\"Review choices visually, receive submission notifications and export results to CSV or JSON.\";s:11:\"screenshots\";N;s:2:\"id\";s:4:\"9080\";s:7:\"created\";s:19:\"2026-07-13 11:44:47\";s:7:\"updated\";s:19:\"2026-07-13 12:32:56\";}s:12:\"premium_slug\";s:27:\"foogallery-proofing-premium\";}}}s:7:\"created\";i:1792886376;s:9:\"timestamp\";i:1792972776;}s:45:\"get:/v1/users/10592932/plugins/843/plans.json\";O:8:\"stdClass\":3:{s:6:\"result\";O:8:\"stdClass\":1:{s:5:\"plans\";a:5:{i:0;O:14:\"FS_Plugin_Plan\":24:{s:2:\"id\";s:4:\"1180\";s:7:\"updated\";s:19:\"2021-06-03 16:58:12\";s:7:\"created\";s:19:\"2017-03-06 17:13:54\";s:22:\"\0FS_Entity\0_is_updated\";b:0;s:9:\"plugin_id\";s:3:\"843\";s:4:\"name\";s:4:\"free\";s:5:\"title\";s:4:\"Free\";s:11:\"description\";N;s:17:\"is_free_localhost\";b:1;s:17:\"is_block_features\";b:1;s:12:\"license_type\";i:0;s:16:\"is_https_support\";b:0;s:12:\"trial_period\";N;s:23:\"is_require_subscription\";b:0;s:10:\"support_kb\";s:48:\"https://fooplugins.com/documentation/foogallery/\";s:13:\"support_forum\";s:48:\"https://wordpress.org/support/plugin/foogallery/\";s:13:\"support_email\";N;s:13:\"support_phone\";N;s:13:\"support_skype\";s:0:\"\";s:18:\"is_success_manager\";b:0;s:11:\"is_featured\";b:0;s:9:\"is_hidden\";b:0;s:7:\"pricing\";N;s:8:\"features\";N;}i:1;O:14:\"FS_Plugin_Plan\":24:{s:2:\"id\";s:5:\"13794\";s:7:\"updated\";s:19:\"2021-06-15 12:19:28\";s:7:\"created\";s:19:\"2021-05-08 1